import { describe, expect, it } from 'vitest'
import { PRIM_TYPE_BOX, PRIM_TYPE_CYLINDER, PRIM_TYPE_PRISM, PRIM_TYPE_SPHERE, type Vector } from '@rezless/vm'
import { loadLinkset, World } from '../src/index.js'

// https://wiki.secondlife.com/wiki/LlSitTarget: "If the object has no sit
// target, the avatar is seated at a position chosen by the simulator."
// sit-spot-clicks.test.ts pins clicks on box tops and sides; this file holds
// clicks on cylinders' tops, spheres and prisms, and low clicks on a box's
// side.
//
// Measured on the Aditi beta grid (SLua Tideland, Firestorm 7.3.0 with RLVa,
// 2026-11-23) with one avatar, on an unturned prim without a sit target whose
// bottom rested at z 1996.97, centred at <123, 52> unless the label says
// otherwise (those rows are given as if it stood at <123, 52>). Before each
// click the avatar stood near the prim facing it; the viewer moved its own
// camera, aimed at the prim's centre, and waited for it to settle, then sent
// the sit request with an offset from the prim's centre, as a click on that
// spot does. A script in the prim read the avatar's link with PRIM_POS_LOCAL
// and PRIM_ROT_LOCAL in changed(CHANGED_LINK). Each row gives the shape, size
// and centre height, the avatar's region position and heading in degrees,
// the camera's region position (null: at rest), the offset (null: no click),
// and the seat's position and rotation (null: refused with "There is no
// suitable surface to sit on").

type Shape = 'box' | 'cylinder' | 'sphere' | 'prism'
type Click = [string, Shape, Vector, number, Vector, number, Vector | null, Vector | null, Vector | null, [number, number, number, number] | null]

const AVATAR = 'abcdefab-1234-1234-1234-abcdefabcdef'
const KIND = { box: PRIM_TYPE_BOX, cylinder: PRIM_TYPE_CYLINDER, sphere: PRIM_TYPE_SPHERE, prism: PRIM_TYPE_PRISM }
const v = (x: number, y: number, z: number) => ({ x, y, z })

// Clicks on a cylinder's top. As on a box's top, rays run across the top from
// the clicked spot towards the camera, away from it and towards the avatar.
// Each leaves the edge at a point; the avatar sits at the tangent there
// nearest the spot, 0.09 m out from it and in line with the spot along it,
// facing out along the edge's normal. On a round top this held in 33 of 34
// clicks from two cameras and two avatar places, and in the six clicks on a
// cylinder's top in sit-spot-clicks.test.ts. An oval top's edge is the
// nine-sided polygon through the oval at every 40 degrees from +X; three of
// four clicks on a 1 x 2 m top fit it. A camera steeply above, whose line to
// the centre or a clicked side meets the top first, seats the avatar by the
// same rule.
