async function sit([, shape, size, z, at, heading, camera, click]: Click, turn = { x: 0, y: 0, z: 0, s: 1 }) {
  const world = new World()
  world.addRegion('home', { x: 0, y: 0 })
  const half = heading * Math.PI / 360
  const avatar = world.addAvatar({ region: 'home', key: AVATAR, name: 'av', username: 'av', position: at, rotation: { x: 0, y: 0, z: Math.sin(half), s: Math.cos(half) } })
  const { linkset } = await loadLinkset({ world, region: 'home', owner: AVATAR, position: v(123, 52, z), prims: [{}] })
  const prim = linkset.prims[0]!
  prim.params.size = size
  prim.params.shape = { ...prim.params.shape, kind: KIND[shape] }
  prim.params.rotation = turn
  if (camera) world.setAvatarCamera(avatar, camera)
  return world.getSitResponse(avatar, prim, click ?? undefined)
}

async function check(row: Click, turn?: { x: number; y: number; z: number; s: number }) {
  const response = await sit(row, turn)
  const [, , , , , , camera, , want, rotation] = row
  if (!want) return expect(response).toBeNull()
  const { position, rotation: rot } = response!
  expect(Math.hypot(position.x - want.x, position.y - want.y)).toBeLessThan(camera ? 0.005 : 0.035)
  expect(Math.abs(position.z - want.z)).toBeLessThan(0.005)
  const [qx, qy, qz, qs] = rotation!
  expect(rot!.x * qx + rot!.y * qy + rot!.z * qz + rot!.s * qs).toBeGreaterThan(0.999)
}

describe('where a click seats an avatar on a cylinder, sphere or prism, and low on a box', () => {
  it.each(CYLINDER_TOP)('%s', async (...row) => { await check(row) })
  it.fails.each(CYLINDER_TIE)('%s', async (...row) => { await check(row) })
  it.each(CYLINDER_TURN)('%s', async (...row) => { await check(row) })
  it.each(OVAL_SWITCH)('%s', async (...row) => { await check(row) })
  it.each(OVAL_TURNED)('%s', async (...row) => { await check(row, { x: 0, y: 0, z: Math.sin(Math.PI / 18), s: Math.cos(Math.PI / 18) }) })
  it.each(LOW_TAKEN)('%s', async (...row) => { await check(row) })
  it.fails.each(LOW_REFUSED)('%s', async (...row) => { await check(row) })
  it.fails.each(SPHERE)('%s', async (...row) => { await check(row) })
  it.each(PRISM)('%s', async (...row) => { await check(row) })
  it.fails.each(PRISM_LOWER)('%s', async (...row) => { await check(row) })
})
